#!/bin/bash

# --------------------------------------------------
# Clean files generated by the parametric engine
# --------------------------------------------------

confirm_delete() {

    local prompt=$1
    local answer

    if [ "${CLEAN_YES:-0}" -eq 1 ]; then
        return 0
    fi

    read -r -p "$prompt [y/N]: " answer
    case "$answer" in
        y|Y|yes|YES) return 0 ;;
        *)           return 1 ;;
    esac
}

clean_generated_data() {

    local removed=0

    ui_section "Clean parametric data"

    if [ -d "parametricStudy" ] || [ -d "paramDatabase" ]; then
        if [ "${CLEAN_YES:-0}" -eq 0 ] && [ ! -t 0 ]; then
            ui_error "Cleanup needs confirmation; run interactively or use --yes"
            return 1
        fi
    fi

    if [ -d "parametricStudy" ]; then
        if confirm_delete "Delete parametricStudy (all archived cases)?"; then
            rm -rf "parametricStudy"
            ui_ok "Removed parametricStudy"
            removed=$((removed + 1))
        else
            ui_info "Kept parametricStudy"
        fi
    fi

    if [ -d "paramDatabase" ]; then
        if confirm_delete "Delete paramDatabase (tables, matrices, status)?"; then
            rm -rf "paramDatabase"
            ui_ok "Removed paramDatabase"
            removed=$((removed + 1))
        else
            ui_info "Kept paramDatabase"
        fi
    fi

    for dir in parametricWork parametricLogs parametricStatus coreScalingLogs; do
        if [ -d "$dir" ]; then
            rm -rf "$dir"
            ui_ok "Removed $dir"
            removed=$((removed + 1))
        fi
    done

    rm -f "calculationScript.backup"
    rm -f "${prefix}"[0-9]*.txt
    rm -f paramDatabase/${prefix}[0-9]*.txt
    rm -f paramDatabase/*_mesh.txt

    if [ "$removed" -eq 0 ]; then
        ui_info "Nothing to remove"
    else
        ui_ok "Cleanup complete"
    fi

    return 0
}
